}", "replace": "// Singleton instances
let vectorStoreInstance: VectorStore | null = null;
let qdrantStoreInstance: any | null = null;

/**
 * Vector Store Factory
 * Creates the appropriate vector store based on configuration
 */
export function getVectorStore(): VectorStore | any {
  const provider = process.env.VECTOR_STORE_PROVIDER || 'memory';

  switch (provider) {
    case 'qdrant':
      if (!qdrantStoreInstance) {
        // Lazy import to avoid loading Qdrant client if not needed
        const { QdrantVectorStore } = require('./qdrant-adapter');
        qdrantStoreInstance = new QdrantVectorStore({
          url: process.env.QDRANT_URL || 'http://localhost:6333',
          apiKey: process.env.QDRANT_API_KEY,
          collectionName: process.env.QDRANT_COLLECTION_NAME || 'arkan_vectors',
          vectorDimension: parseInt(process.env.EMBEDDING_DIMENSION || '768', 10),
        });
      }
      return qdrantStoreInstance;

    case 'memory':
    case 'firestore':
    default:
      if (!vectorStoreInstance) {
        vectorStoreInstance = new VectorStore();
      }
      return vectorStoreInstance;
  }
}

/**
 * Reset vector store instance (useful for testing)
 */
export function resetVectorStore(): void {
  vectorStoreInstance = null;
  qdrantStoreInstance = null;
}"}

{"file_path": "src/lib/rag/vector-store-interface.ts", "initial_content": "/**
 * Vector Store Interface
 * 
 * This defines the common interface that all vector store implementations must follow.
 * This allows easy switching between different vector database backends.
 */

export interface DocumentChunk {
  id: string;
  content: string;
  embedding?: number[];
  metadata: {
    projectId?: string;
    userId?: string;
    sourceFile?: string;
    chunkIndex: number;
    timestamp: number;
    type: 'report' | 'reference' | 'context' | 'user_upload';
  };
}

export interface SearchResult {
  chunk: DocumentChunk;
  score: number;
}

export interface SearchOptions {
  topK?: number;
  minScore?: number;
  filter?: Partial<DocumentChunk['metadata']>;
}

export interface VectorStoreStats {
  totalChunks: number;
  vectorDimension: number;
  indexedFields?: string[];
}

/**
 * Base interface that all vector stores must implement
 */
export interface IVectorStore {
  /**
   * Add a single document chunk
   */
  addChunk(chunk: DocumentChunk): Promise<void>;

  /**
   * Add multiple chunks in batch
   */
  addChunks(chunks: DocumentChunk[]): Promise<void>;

  /**
   * Search for similar chunks
   */
  search(
    queryEmbedding: number[],
    options?: SearchOptions
  ): Promise<SearchResult[]>;

  /**
   * Load or prepare chunks for a project (implementation specific)
   */
  loadProjectChunks(projectId: string): Promise<void>;

  /**
   * Delete chunks for a specific project
   */
  deleteProjectChunks?(projectId: string): Promise<void>;

  /**
   * Delete a specific chunk
   */
  deleteChunk?(chunkId: string): Promise<void>;

  /**
   * Clear all data
   */
  clear(): void | Promise<void>;

  /**
   * Get total number of chunks
   */
  size(): number | Promise<number>;

  /**
   * Get statistics about the vector store
   */
  getStats?(): Promise<VectorStoreStats>;

  /**
   * Health check
   */
  healthCheck?(): Promise<boolean>;
}
"}

{"file_path": "src/lib/rag/config.ts", "initial_content": "/**
 * RAG Configuration
 * 
 * Centralized configuration for RAG and vector search functionality.
 */

export const RAGConfig = {
  // Vector Store Configuration
  vectorStore: {
    provider: process.env.VECTOR_STORE_PROVIDER || 'memory',
    dimension: parseInt(process.env.EMBEDDING_DIMENSION || '768', 10),
  },

  // Qdrant Configuration
  qdrant: {
    url: process.env.QDRANT_URL || 'http://localhost:6333',
    apiKey: process.env.QDRANT_API_KEY,
    collectionName: process.env.QDRANT_COLLECTION_NAME || 'arkan_vectors',
    batchSize: 100,
  },

  // Ollama Configuration
  ollama: {
    baseUrl: process.env.OLLAMA_BASE_URL || 'http://185.190.140.93:11434',
    embeddingModel: process.env.OLLAMA_EMBEDDING_MODEL || 'nomic-embed-text',
  },

  // Chunking Configuration
  chunking: {
    chunkSize: 500,
    overlap: 50,
    preserveParagraphs: true,
  },

  // Search Configuration
  search: {
    defaultTopK: 5,
    defaultMinScore: 0.5,
    maxTopK: 20,
  },

  // Cache Configuration
  cache: {
    embeddingCacheTTL: 24 * 60 * 60 * 1000, // 24 hours
    searchResultCacheTTL: 60 * 60 * 1000, // 1 hour
  },
} as const;

/**
 * Validate RAG configuration
 */
export function validateRAGConfig(): { valid: boolean; errors: string[] } {
  const errors: string[] = [];

  // Validate vector dimension
  if (RAGConfig.vectorStore.dimension <= 0) {
    errors.push('EMBEDDING_DIMENSION must be a positive number');
  }

  // Validate Qdrant URL if using Qdrant
  if (RAGConfig.vectorStore.provider === 'qdrant') {
    if (!RAGConfig.qdrant.url) {
      errors.push('QDRANT_URL is required when using Qdrant provider');
    }

    try {
      new URL(RAGConfig.qdrant.url);
    } catch {
      errors.push('QDRANT_URL must be a valid URL');
    }
  }

  // Validate Ollama URL
  try {
    new URL(RAGConfig.ollama.baseUrl);
  } catch {
    errors.push('OLLAMA_BASE_URL must be a valid URL');
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}
"}

{"file_path": "scripts/migrate-to-qdrant.ts", "initial_content": "/**
 * Migration Script: Transfer vectors from Firestore to Qdrant
 * 
 * Usage:
 *   npx ts-node scripts/migrate-to-qdrant.ts
 * 
 * This script:
 * 1. Reads all vector embeddings from Firestore
 * 2. Transfers them to Qdrant
 * 3. Validates the migration
 * 4. Optionally cleans up old data
 */

import { adminDb as db } from '@/lib/firebase/server-init';
import { collection, getDocs } from 'firebase/firestore';
import { QdrantVectorStore } from '@/lib/rag/qdrant-adapter';
import { RAGConfig } from '@/lib/rag/config';
import type { DocumentChunk } from '@/lib/rag/vector-store-interface';

interface MigrationStats {
  totalDocuments: number;
  successfulMigrations: number;
  failedMigrations: number;
  errors: string[];
  startTime: Date;
  endTime?: Date;
  duration?: number;
}

async function migrateToQdrant(options: {
  dryRun?: boolean;
  cleanupFirestore?: boolean;
  batchSize?: number;
}): Promise<MigrationStats> {
  const { dryRun = false, cleanupFirestore = false, batchSize = 100 } = options;

  const stats: MigrationStats = {
    totalDocuments: 0,
    successfulMigrations: 0,
    failedMigrations: 0,
    errors: [],
    startTime: new Date(),
  };

  console.log('🚀 Starting migration to Qdrant...');
  console.log(`Mode: ${dryRun ? 'DRY RUN' : 'LIVE'}`);
  console.log(`Cleanup Firestore after migration: ${cleanupFirestore}`);
  console.log('');

  try {
    // Initialize Qdrant
    const qdrantStore = new QdrantVectorStore({
      url: RAGConfig.qdrant.url,
      apiKey: RAGConfig.qdrant.apiKey,
      collectionName: RAGConfig.qdrant.collectionName,
      vectorDimension: RAGConfig.vectorStore.dimension,
    });

    // Health check
    console.log('🔍 Checking Qdrant connection...');
    const isHealthy = await qdrantStore.healthCheck();
    if (!isHealthy) {
      throw new Error('Qdrant is not accessible. Please ensure the service is running.');
    }
    console.log('✅ Qdrant is healthy\n');

    // Initialize collection
    await qdrantStore.initialize();

    // Get current Qdrant stats
    const currentStats = await qdrantStore.getStats();
    console.log(`📊 Current Qdrant stats:`);
    console.log(`  - Total chunks: ${currentStats.totalChunks}`);
    console.log(`  - Vector dimension: ${currentStats.vectorDimension}\n`);

    // Read from Firestore
    console.log('📖 Reading vectors from Firestore...');
    const collectionRef = collection(db, 'vector_embeddings');
    const snapshot = await getDocs(collectionRef);
    stats.totalDocuments = snapshot.size;

    console.log(`Found ${stats.totalDocuments} documents in Firestore\n`);

    if (stats.totalDocuments === 0) {
      console.log('⚠️  No documents to migrate');
      stats.endTime = new Date();
      stats.duration = stats.endTime.getTime() - stats.startTime.getTime();
      return stats;
    }

    // Process documents in batches
    const chunks: DocumentChunk[] = [];
    let batch: DocumentChunk[] = [];

    snapshot.forEach((doc) => {
      try {
        const data = doc.data();

        // Validate document structure
        if (!data.content || !data.embedding || !data.metadata) {
          stats.errors.push(`Document ${doc.id} missing required fields`);
          stats.failedMigrations++;
          return;
        }

        const chunk: DocumentChunk = {
          id: doc.id,
          content: data.content,
          embedding: data.embedding,
          metadata: {
            projectId: data.metadata.projectId,
            userId: data.metadata.userId,
            sourceFile: data.metadata.sourceFile,
            chunkIndex: data.metadata.chunkIndex,
            timestamp: data.metadata.timestamp,
            type: data.metadata.type || 'context',
          },
        };

        batch.push(chunk);
        chunks.push(chunk);

      } catch (error) {
        stats.errors.push(`Error processing document ${doc.id}: ${error instanceof Error ? error.message : 'Unknown error'}`);
        stats.failedMigrations++;
      }
    });

    // Migrate to Qdrant
    if (!dryRun && batch.length > 0) {
      console.log(`📤 Migrating ${batch.length} chunks to Qdrant...`);

      for (let i = 0; i < batch.length; i += batchSize) {
        const currentBatch = batch.slice(i, i + batchSize);
        const batchNum = Math.floor(i / batchSize) + 1;
        const totalBatches = Math.ceil(batch.length / batchSize);

        try {
          await qdrantStore.addChunks(currentBatch);
          stats.successfulMigrations += currentBatch.length;

          console.log(`  ✓ Batch ${batchNum}/${totalBatches} migrated (${currentBatch.length} chunks)`);
        } catch (error) {
          stats.failedMigrations += currentBatch.length;
          stats.errors.push(`Batch ${batchNum} failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
          console.error(`  ✗ Batch ${batchNum}/${totalBatches} failed`);
        }
      }
    } else if (dryRun) {
      console.log(`🔍 DRY RUN: Would migrate ${batch.length} chunks`);
      stats.successfulMigrations = batch.length;
    }

    // Verify migration
    console.log('\n🔍 Verifying migration...');
    const finalStats = await qdrantStore.getStats();
    console.log(`  - Total chunks in Qdrant: ${finalStats.totalChunks}`);

    if (!dryRun && finalStats.totalChunks >= currentStats.totalChunks + stats.successfulMigrations) {
      console.log('  ✅ Migration verified successfully');
    } else if (!dryRun) {
      console.log('  ⚠️  Warning: Chunk count mismatch. Please verify manually.');
    }

    // Cleanup Firestore (if requested)
    if (cleanupFirestore && !dryRun && stats.successfulMigrations > 0) {
      console.log('\n🧹 Cleaning up Firestore...');
      console.log('⚠️  This feature is not implemented yet for safety.');
      console.log('   Please manually delete Firestore documents after verifying the migration.');
    }

  } catch (error) {
    stats.errors.push(`Fatal error: ${error instanceof Error ? error.message : 'Unknown error'}`);
    console.error('\n❌ Migration failed:', error);
  }

  stats.endTime = new Date();
  stats.duration = stats.endTime.getTime() - stats.startTime.getTime();

  return stats;
}

/**
 * Print migration summary
 */
function printSummary(stats: MigrationStats): void {
  console.log('\n' + '='.repeat(60));
  console.log('📊 MIGRATION SUMMARY');
  console.log('='.repeat(60));
  console.log(`Total documents:        ${stats.totalDocuments}`);
  console.log(`Successful migrations:  ${stats.successfulMigrations}`);
  console.log(`Failed migrations:      ${stats.failedMigrations}`);
  console.log(`Duration:               ${stats.duration ? (stats.duration / 1000).toFixed(2) + 's' : 'N/A'}`);

  if (stats.errors.length > 0) {
    console.log(`\nErrors (${stats.errors.length}):`);
    stats.errors.slice(0, 10).forEach((error, idx) => {
      console.log(`  ${idx + 1}. ${error}`);
    });
    if (stats.errors.length > 10) {
      console.log(`  ... and ${stats.errors.length - 10} more errors`);
    }
  }

  console.log('='.repeat(60));
}

/**
 * Main execution
 */
async function main() {
  const args = process.argv.slice(2);
  const dryRun = args.includes('--dry-run');
  const cleanup = args.includes('--cleanup');
  const batchSize = parseInt(args.find(arg => arg.startsWith('--batch-size='))?.split('=')[1] || '100', 10);

  if (args.includes('--help')) {
    console.log(`
Migration Script: Transfer vectors from Firestore to Qdrant

Usage:
  npx ts-node scripts/migrate-to-qdrant.ts [options]

Options:
  --dry-run              Run migration without making changes
  --cleanup              Delete Firestore documents after successful migration
  --batch-size=N         Number of documents per batch (default: 100)
  --help                 Show this help message

Examples:
  # Dry run to see what would be migrated
  npx ts-node scripts/migrate-to-qdrant.ts --dry-run

  # Actual migration
  npx ts-node scripts/migrate-to-qdrant.ts

  # Migration with cleanup
  npx ts-node scripts/migrate-to-qdrant.ts --cleanup

  # Custom batch size
  npx ts-node scripts/migrate-to-qdrant.ts --batch-size=50
    `);
    process.exit(0);
  }

  const stats = await migrateToQdrant({
    dryRun,
    cleanupFirestore: cleanup,
    batchSize,
  });

  printSummary(stats);

  if (stats.failedMigrations > 0) {
    process.exit(1);
  }
}

// Run if executed directly
if (require.main === module) {
  main().catch(console.error);
}

export { migrateToQdrant, MigrationStats };
"}

{"file_path": "scripts/qdrant-utils.ts", "initial_content": "/**
 * Qdrant Utility Scripts
 * 
 * Helper scripts for managing Qdrant vector database
 */

import { QdrantVectorStore } from '@/lib/rag/qdrant-adapter';
import { RAGConfig } from '@/lib/rag/config';

/**
 * Initialize Qdrant collection
 */
export async function initializeQdrant(): Promise<void> {
  console.log('🚀 Initializing Qdrant...');

  const qdrant = new QdrantVectorStore({
    url: RAGConfig.qdrant.url,
    apiKey: RAGConfig.qdrant.apiKey,
    collectionName: RAGConfig.qdrant.collectionName,
    vectorDimension: RAGConfig.vectorStore.dimension,
  });

  await qdrant.initialize();
  console.log('✅ Qdrant initialized successfully');
}

/**
 * Get Qdrant statistics
 */
export async function getQdrantStats(): Promise<void> {
  console.log('📊 Fetching Qdrant statistics...\n');

  const qdrant = new QdrantVectorStore({
    url: RAGConfig.qdrant.url,
    apiKey: RAGConfig.qdrant.apiKey,
    collectionName: RAGConfig.qdrant.collectionName,
    vectorDimension: RAGConfig.vectorStore.dimension,
  });

  const isHealthy = await qdrant.healthCheck();
  console.log(`Health Status: ${isHealthy ? '✅ Healthy' : '❌ Unhealthy'}`);

  if (isHealthy) {
    const stats = await qdrant.getStats();
    console.log(`\nCollection: ${RAGConfig.qdrant.collectionName}`);
    console.log(`Total Chunks: ${stats.totalChunks.toLocaleString()}`);
    console.log(`Vector Dimension: ${stats.vectorDimension}`);
    console.log(`Indexed Fields: ${stats.indexedFields?.join(', ') || 'N/A'}`);
  }
}

/**
 * Clear Qdrant collection (WARNING: Destructive!)
 */
export async function clearQdrant(confirm: boolean = false): Promise<void> {
  if (!confirm) {
    console.log('⚠️  This will delete ALL data from Qdrant!');
    console.log('Run with --confirm flag if you are sure.');
    return;
  }

  console.log('🗑️  Clearing Qdrant collection...');

  const qdrant = new QdrantVectorStore({
    url: RAGConfig.qdrant.url,
    apiKey: RAGConfig.qdrant.apiKey,
    collectionName: RAGConfig.qdrant.collectionName,
    vectorDimension: RAGConfig.vectorStore.dimension,
  });

  await qdrant.clear();
  console.log('✅ Qdrant collection cleared');
}

/**
 * Test Qdrant connection
 */
export async function testQdrantConnection(): Promise<void> {
  console.log('🔍 Testing Qdrant connection...\n');
  console.log(`URL: ${RAGConfig.qdrant.url}`);
  console.log(`Collection: ${RAGConfig.qdrant.collectionName}`);
  console.log(`Vector Dimension: ${RAGConfig.vectorStore.dimension}\n`);

  const qdrant = new QdrantVectorStore({
    url: RAGConfig.qdrant.url,
    apiKey: RAGConfig.qdrant.apiKey,
    collectionName: RAGConfig.qdrant.collectionName,
    vectorDimension: RAGConfig.vectorStore.dimension,
  });

  try {
    const isHealthy = await qdrant.healthCheck();
    if (isHealthy) {
      console.log('✅ Connection successful!');
      await qdrant.initialize();
      console.log('✅ Collection initialized!');

      const stats = await qdrant.getStats();
      console.log(`\n📊 Collection has ${stats.totalChunks} chunks`);
    } else {
      console.log('❌ Connection failed - Qdrant not responding');
      process.exit(1);
    }
  } catch (error) {
    console.error('❌ Connection error:', error instanceof Error ? error.message : error);
    process.exit(1);
  }
}

/**
 * Main CLI handler
 */
async function main() {
  const command = process.argv[2];
  const flags = process.argv.slice(3);

  switch (command) {
    case 'init':
      await initializeQdrant();
      break;

    case 'stats':
      await getQdrantStats();
      break;

    case 'clear':
      await clearQdrant(flags.includes('--confirm'));
      break;

    case 'test':
      await testQdrantConnection();
      break;

    default:
      console.log(`
Qdrant Utility Scripts

Usage:
  npx ts-node scripts/qdrant-utils.ts <command> [options]

Commands:
  init       Initialize Qdrant collection
  stats      Show collection statistics
  clear      Clear all data (use --confirm flag)
  test       Test Qdrant connection

Examples:
  npx ts-node scripts/qdrant-utils.ts init
  npx ts-node scripts/qdrant-utils.ts stats
  npx ts-node scripts/qdrant-utils.ts test
  npx ts-node scripts/qdrant-utils.ts clear --confirm
      `);
      break;
  }
}

// Run if executed directly
if (require.main === module) {
  main().catch(console.error);
}
"}

{"file_path": "src/app/api/rag/health/route.ts", "initial_content": "/**
 * RAG Health Check API Endpoint
 * 
 * Returns the health status of the RAG system including:
 * - Vector store connectivity
 * - Ollama embedding service
 * - Collection statistics
 */

import { NextRequest, NextResponse } from 'next/server';
import { getVectorStore } from '@/lib/rag/vector-store';
import { RAGConfig, validateRAGConfig } from '@/lib/rag/config';

export async function GET(request: NextRequest) {
  try {
    const checks = {
      config: { status: 'unknown' as 'ok' | 'error', details: {} as any },
      vectorStore: { status: 'unknown' as 'ok' | 'error', details: {} as any },
      ollama: { status: 'unknown' as 'ok' | 'error', details: {} as any },
    };

    // 1. Validate configuration
    const configValidation = validateRAGConfig();
    checks.config.status = configValidation.valid ? 'ok' : 'error';
    checks.config.details = {
      provider: RAGConfig.vectorStore.provider,
      dimension: RAGConfig.vectorStore.dimension,
      errors: configValidation.errors,
    };

    // 2. Check vector store
    try {
      const vectorStore = getVectorStore();

      // Check if it's Qdrant with healthCheck method
      if (typeof vectorStore.healthCheck === 'function') {
        const isHealthy = await vectorStore.healthCheck();
        checks.vectorStore.status = isHealthy ? 'ok' : 'error';

        if (isHealthy) {
          const stats = await vectorStore.getStats();
          checks.vectorStore.details = {
            type: 'qdrant',
            url: RAGConfig.qdrant.url,
            collection: RAGConfig.qdrant.collectionName,
            totalChunks: stats.totalChunks,
            vectorDimension: stats.vectorDimension,
          };
        } else {
          checks.vectorStore.details = { error: 'Health check failed' };
        }
      } else {
        // In-memory store
        const size = typeof vectorStore.size === 'function' 
          ? await vectorStore.size() 
          : vectorStore.size();

        checks.vectorStore.status = 'ok';
        checks.vectorStore.details = {
          type: 'memory',
          totalChunks: size,
        };
      }
    } catch (error) {
      checks.vectorStore.status = 'error';
      checks.vectorStore.details = {
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }

    // 3. Check Ollama embedding service
    try {
      const response = await fetch(`${RAGConfig.ollama.baseUrl}/api/tags`, {
        method: 'GET',
        signal: AbortSignal.timeout(5000), // 5 second timeout
      });

      if (response.ok) {
        const data = await response.json();
        const hasEmbeddingModel = data.models?.some(
          (m: any) => m.name.includes(RAGConfig.ollama.embeddingModel)
        );

        checks.ollama.status = hasEmbeddingModel ? 'ok' : 'error';
        checks.ollama.details = {
          url: RAGConfig.ollama.baseUrl,
          model: RAGConfig.ollama.embeddingModel,
          modelAvailable: hasEmbeddingModel,
          availableModels: data.models?.map((m: any) => m.name).slice(0, 5) || [],
        };
      } else {
        checks.ollama.status = 'error';
        checks.ollama.details = {
          error: `HTTP ${response.status}: ${response.statusText}`,
        };
      }
    } catch (error) {
      checks.ollama.status = 'error';
      checks.ollama.details = {
        error: error instanceof Error ? error.message : 'Connection failed',
        url: RAGConfig.ollama.baseUrl,
      };
    }

    // Determine overall status
    const allOk = Object.values(checks).every(check => check.status === 'ok');
    const overallStatus = allOk ? 'healthy' : 'degraded';

    return NextResponse.json({
      status: overallStatus,
      timestamp: new Date().toISOString(),
      checks,
      config: {
        provider: RAGConfig.vectorStore.provider,
        embeddingModel: RAGConfig.ollama.embeddingModel,
        vectorDimension: RAGConfig.vectorStore.dimension,
      },
    });

  } catch (error) {
    console.error('Health check error:', error);

    return NextResponse.json(
      {
        status: 'error',
        timestamp: new Date().toISOString(),
        error: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    );
  }
}
"}

