{"file_path": "src/lib/rag/__tests__/qdrant-adapter.test.ts", "initial_content": "/**
 * Tests for Qdrant Vector Store Adapter
 */

import { QdrantVectorStore } from '../qdrant-adapter';
import type { DocumentChunk } from '../vector-store-interface';

// Mock Qdrant client
jest.mock('@qdrant/js-client-rest', () => ({
  QdrantClient: jest.fn().mockImplementation(() => ({
    getCollections: jest.fn().mockResolvedValue({ collections: [] }),
    createCollection: jest.fn().mockResolvedValue({}),
    createPayloadIndex: jest.fn().mockResolvedValue({}),
    upsert: jest.fn().mockResolvedValue({}),
    search: jest.fn().mockResolvedValue([]),
    delete: jest.fn().mockResolvedValue({}),
    deleteCollection: jest.fn().mockResolvedValue({}),
    getCollection: jest.fn().mockResolvedValue({ points_count: 0 }),
  })),
}));

describe('QdrantVectorStore', () => {
  let qdrantStore: QdrantVectorStore;

  beforeEach(() => {
    qdrantStore = new QdrantVectorStore({
      url: 'http://localhost:6333',
      collectionName: 'test_collection',
      vectorDimension: 768,
    });
  });

  describe('initialization', () => {
    it('should initialize collection if it does not exist', async () => {
      await qdrantStore.initialize();
      // If this doesn't throw, initialization succeeded
      expect(true).toBe(true);
    });

    it('should not recreate collection if it already exists', async () => {
      const mockClient = (qdrantStore as any).client;
      mockClient.getCollections.mockResolvedValueOnce({
        collections: [{ name: 'test_collection' }],
      });

      await qdrantStore.initialize();
      expect(mockClient.createCollection).not.toHaveBeenCalled();
    });
  });

  describe('addChunk', () => {
    it('should add a single chunk successfully', async () => {
      const chunk: DocumentChunk = {
        id: 'test-1',
        content: 'Test content',
        embedding: new Array(768).fill(0.1),
        metadata: {
          projectId: 'project-1',
          userId: 'user-1',
          chunkIndex: 0,
          timestamp: Date.now(),
          type: 'context',
        },
      };

      await qdrantStore.addChunk(chunk);
      expect(true).toBe(true); // No error thrown
    });

    it('should throw error if chunk has no embedding', async () => {
      const chunk: DocumentChunk = {
        id: 'test-1',
        content: 'Test content',
        metadata: {
          chunkIndex: 0,
          timestamp: Date.now(),
          type: 'context',
        },
      };

      await expect(qdrantStore.addChunk(chunk)).rejects.toThrow();
    });
  });

  describe('addChunks', () => {
    it('should add multiple chunks in batch', async () => {
      const chunks: DocumentChunk[] = [
        {
          id: 'test-1',
          content: 'Content 1',
          embedding: new Array(768).fill(0.1),
          metadata: {
            chunkIndex: 0,
            timestamp: Date.now(),
            type: 'context',
          },
        },
        {
          id: 'test-2',
          content: 'Content 2',
          embedding: new Array(768).fill(0.2),
          metadata: {
            chunkIndex: 1,
            timestamp: Date.now(),
            type: 'context',
          },
        },
      ];

      await qdrantStore.addChunks(chunks);
      expect(true).toBe(true);
    });

    it('should handle empty array', async () => {
      await qdrantStore.addChunks([]);
      expect(true).toBe(true);
    });
  });

  describe('search', () => {
    it('should search with query embedding', async () => {
      const queryEmbedding = new Array(768).fill(0.5);

      const mockClient = (qdrantStore as any).client;
      mockClient.search.mockResolvedValueOnce([
        {
          id: 'result-1',
          score: 0.95,
          payload: {
            content: 'Result content',
            projectId: 'project-1',
            chunkIndex: 0,
            timestamp: Date.now(),
            type: 'context',
          },
        },
      ]);

      const results = await qdrantStore.search(queryEmbedding, { topK: 5 });

      expect(results).toHaveLength(1);
      expect(results[0].score).toBe(0.95);
      expect(results[0].chunk.content).toBe('Result content');
    });

    it('should apply filters correctly', async () => {
      const queryEmbedding = new Array(768).fill(0.5);
      const mockClient = (qdrantStore as any).client;

      await qdrantStore.search(queryEmbedding, {
        topK: 5,
        filter: {
          projectId: 'project-1',
          type: 'context',
        },
      });

      expect(mockClient.search).toHaveBeenCalledWith(
        'test_collection',
        expect.objectContaining({
          filter: {
            must: expect.arrayContaining([
              { key: 'projectId', match: { value: 'project-1' } },
              { key: 'type', match: { value: 'context' } },
            ]),
          },
        })
      );
    });
  });

  describe('deleteProjectChunks', () => {
    it('should delete all chunks for a project', async () => {
      const mockClient = (qdrantStore as any).client;

      await qdrantStore.deleteProjectChunks('project-1');

      expect(mockClient.delete).toHaveBeenCalledWith(
        'test_collection',
        expect.objectContaining({
          filter: {
            must: [{ key: 'projectId', match: { value: 'project-1' } }],
          },
        })
      );
    });
  });

  describe('healthCheck', () => {
    it('should return true when connection is healthy', async () => {
      const isHealthy = await qdrantStore.healthCheck();
      expect(isHealthy).toBe(true);
    });

    it('should return false when connection fails', async () => {
      const mockClient = (qdrantStore as any).client;
      mockClient.getCollections.mockRejectedValueOnce(new Error('Connection failed'));

      const isHealthy = await qdrantStore.healthCheck();
      expect(isHealthy).toBe(false);
    });
  });

  describe('getStats', () => {
    it('should return collection statistics', async () => {
      const mockClient = (qdrantStore as any).client;
      mockClient.getCollection.mockResolvedValueOnce({
        points_count: 1000,
      });

      const stats = await qdrantStore.getStats();

      expect(stats.totalChunks).toBe(1000);
      expect(stats.vectorDimension).toBe(768);
      expect(stats.indexedFields).toContain('projectId');
    });
  });
});
"}

{"file_path": "src/lib/rag/__tests__/integration.test.ts", "initial_content": "/**
 * Integration Tests for RAG System with Qdrant
 * 
 * These tests verify the full RAG pipeline:
 * 1. Document indexing
 * 2. Vector storage
 * 3. Context retrieval
 * 4. Search functionality
 * 
 * Note: These tests require a running Qdrant instance
 */

import { indexDocument } from '../indexer';
import { retrieveContext } from '../retrieval';
import { getVectorStore, resetVectorStore } from '../vector-store';
import { RAGConfig } from '../config';

// Skip these tests if Qdrant is not available
const QDRANT_AVAILABLE = process.env.VECTOR_STORE_PROVIDER === 'qdrant';

describe.skip('RAG Integration Tests with Qdrant', () => {
  // Only run if Qdrant is configured
  if (!QDRANT_AVAILABLE) {
    it.skip('Qdrant not configured - skipping integration tests', () => {});
    return;
  }

  beforeEach(() => {
    resetVectorStore();
  });

  describe('Document Indexing and Retrieval', () => {
    it('should index a document and retrieve relevant context', async () => {
      const testDocument = `
        Artificial Intelligence (AI) is transforming the world of technology.
        Machine learning algorithms enable computers to learn from data.
        Deep learning uses neural networks with multiple layers.
        Natural language processing helps computers understand human language.
      `;

      // Index the document
      const result = await indexDocument(testDocument, {
        projectId: 'test-project-1',
        userId: 'test-user-1',
        type: 'context',
        chunkSize: 100,
      });

      expect(result.success).toBe(true);
      expect(result.chunksCreated).toBeGreaterThan(0);

      // Wait a bit for indexing to complete
      await new Promise(resolve => setTimeout(resolve, 1000));

      // Retrieve context
      const retrieval = await retrieveContext('What is machine learning?', {
        projectId: 'test-project-1',
        topK: 3,
        minScore: 0.3,
      });

      expect(retrieval.sources.length).toBeGreaterThan(0);
      expect(retrieval.context).toContain('machine learning');
    }, 15000);

    it('should filter results by project ID', async () => {
      // Index documents for different projects
      await indexDocument('Project A content about databases', {
        projectId: 'project-a',
        type: 'context',
      });

      await indexDocument('Project B content about machine learning', {
        projectId: 'project-b',
        type: 'context',
      });

      await new Promise(resolve => setTimeout(resolve, 1000));

      // Search in project A
      const resultsA = await retrieveContext('databases', {
        projectId: 'project-a',
        topK: 5,
      });

      // Results should be from project A
      resultsA.sources.forEach(source => {
        expect(source.content).toContain('Project A');
      });
    }, 15000);
  });

  describe('Vector Store Operations', () => {
    it('should handle large batch indexing', async () => {
      const documents = Array.from({ length: 50 }, (_, i) => ({
        content: `This is test document ${i} with some content about topic ${i % 10}.`,
        options: {
          projectId: 'batch-test',
          type: 'context' as const,
        },
      }));

      const results = await Promise.all(
        documents.map(doc => indexDocument(doc.content, doc.options))
      );

      const successful = results.filter(r => r.success).length;
      expect(successful).toBe(documents.length);

      const vectorStore = getVectorStore();
      if (typeof vectorStore.getStats === 'function') {
        const stats = await vectorStore.getStats();
        expect(stats.totalChunks).toBeGreaterThan(0);
      }
    }, 30000);

    it('should delete project chunks', async () => {
      await indexDocument('Test document for deletion', {
        projectId: 'delete-test',
        type: 'context',
      });

      await new Promise(resolve => setTimeout(resolve, 1000));

      const vectorStore = getVectorStore();
      if (typeof vectorStore.deleteProjectChunks === 'function') {
        await vectorStore.deleteProjectChunks('delete-test');

        // Verify deletion
        const retrieval = await retrieveContext('test document', {
          projectId: 'delete-test',
          topK: 5,
        });

        expect(retrieval.sources.length).toBe(0);
      }
    }, 15000);
  });

  describe('Search Quality', () => {
    beforeAll(async () => {
      // Index test documents with known content
      const testDocs = [
        {
          content: 'Python is a high-level programming language known for its simplicity.',
          metadata: { sourceFile: 'python-intro.txt' },
        },
        {
          content: 'JavaScript is primarily used for web development and runs in browsers.',
          metadata: { sourceFile: 'js-intro.txt' },
        },
        {
          content: 'React is a JavaScript library for building user interfaces.',
          metadata: { sourceFile: 'react-intro.txt' },
        },
      ];

      for (const doc of testDocs) {
        await indexDocument(doc.content, {
          projectId: 'search-quality-test',
          sourceFile: doc.metadata.sourceFile,
          type: 'context',
        });
      }

      await new Promise(resolve => setTimeout(resolve, 2000));
    });

    it('should return most relevant results first', async () => {
      const retrieval = await retrieveContext('Tell me about JavaScript', {
        projectId: 'search-quality-test',
        topK: 3,
      });

      expect(retrieval.sources.length).toBeGreaterThan(0);

      // First result should be about JavaScript
      const firstResult = retrieval.sources[0];
      expect(firstResult.content.toLowerCase()).toContain('javascript');

      // Should have high relevance score
      expect(firstResult.score).toBeGreaterThan(0.6);
    }, 15000);
  });
});
"}

{"file_path": "scripts/test-qdrant-indexing.ts", "initial_content": "/**
 * Test Script: Index Documents into Qdrant
 * 
 * This script demonstrates how to index documents into Qdrant
 * and verify the results.
 * 
 * Usage:
 *   npx tsx scripts/test-qdrant-indexing.ts
 */

import { indexDocument, retrieveContext } from '@/lib/rag';
import { getVectorStore } from '@/lib/rag/vector-store';

// Test documents with diverse content
const testDocuments = [
  {
    content: `
      Artificial Intelligence (AI) is transforming the world of technology. 
      Machine learning algorithms enable computers to learn from data without 
      being explicitly programmed. Deep learning, a subset of machine learning, 
      uses neural networks with multiple layers to process complex patterns.

      AI applications include natural language processing, computer vision, 
      robotics, and autonomous systems. Modern AI systems can perform tasks 
      that previously required human intelligence, such as language translation, 
      image recognition, and decision-making.
    `,
    metadata: {
      projectId: 'test-ai-project',
      userId: 'demo-user',
      sourceFile: 'ai-introduction.txt',
      type: 'context' as const,
    },
  },
  {
    content: `
      React is a JavaScript library for building user interfaces. 
      It was developed by Facebook and is now maintained by Meta and 
      a community of developers. React uses a component-based architecture, 
      allowing developers to create reusable UI components.

      Key features of React include the Virtual DOM for efficient rendering, 
      JSX syntax for writing components, and hooks for managing state and 
      side effects. React is widely used for building single-page applications 
      and mobile apps with React Native.
    `,
    metadata: {
      projectId: 'test-web-project',
      userId: 'demo-user',
      sourceFile: 'react-basics.txt',
      type: 'reference' as const,
    },
  },
  {
    content: `
      Database management systems (DBMS) are essential for storing and 
      retrieving data efficiently. SQL databases like PostgreSQL and MySQL 
      use structured schemas and ACID transactions. NoSQL databases like 
      MongoDB and Cassandra offer flexible schemas and horizontal scaling.

      Vector databases like Qdrant are specialized for storing and searching 
      high-dimensional vectors, making them ideal for AI and machine learning 
      applications. They support similarity search, which is crucial for 
      recommendation systems and semantic search.
    `,
    metadata: {
      projectId: 'test-db-project',
      userId: 'demo-user',
      sourceFile: 'database-overview.txt',
      type: 'context' as const,
    },
  },
  {
    content: `
      Next.js is a React framework for building full-stack web applications. 
      It provides features like server-side rendering, static site generation, 
      and API routes. Next.js 15 introduces the App Router with improved 
      performance and developer experience.

      Key features include automatic code splitting, built-in CSS support, 
      image optimization, and TypeScript support. Next.js is used by companies 
      like Netflix, TikTok, and Twitch for building production applications.
    `,
    metadata: {
      projectId: 'test-web-project',
      userId: 'demo-user',
      sourceFile: 'nextjs-guide.txt',
      type: 'reference' as const,
    },
  },
  {
    content: `
      Vector embeddings are numerical representations of text, images, or 
      other data types in a high-dimensional space. They capture semantic 
      meaning, allowing similar items to be close together in the vector space.

      Embedding models like BERT, GPT, and nomic-embed-text convert text into 
      dense vectors. These vectors enable semantic search, where queries find 
      results based on meaning rather than exact keyword matches. This is the 
      foundation of Retrieval-Augmented Generation (RAG) systems.
    `,
    metadata: {
      projectId: 'test-ai-project',
      userId: 'demo-user',
      sourceFile: 'embeddings-explained.txt',
      type: 'context' as const,
    },
  },
];

/**
 * Index all test documents
 */
async function indexTestDocuments() {
  console.log('📚 Starting document indexing...\n');

  const results = [];

  for (let i = 0; i < testDocuments.length; i++) {
    const doc = testDocuments[i];
    console.log(`📄 Indexing document ${i + 1}/${testDocuments.length}:`);
    console.log(`   Source: ${doc.metadata.sourceFile}`);
    console.log(`   Project: ${doc.metadata.projectId}`);
    console.log(`   Type: ${doc.metadata.type}`);

    try {
      const result = await indexDocument(doc.content, {
        projectId: doc.metadata.projectId,
        userId: doc.metadata.userId,
        sourceFile: doc.metadata.sourceFile,
        type: doc.metadata.type,
        chunkSize: 300,
        overlap: 50,
      });

      if (result.success) {
        console.log(`   ✅ Indexed successfully: ${result.chunksCreated} chunks created\n`);
        results.push({ ...doc.metadata, chunksCreated: result.chunksCreated });
      } else {
        console.log(`   ❌ Failed: ${result.error}\n`);
        results.push({ ...doc.metadata, error: result.error });
      }
    } catch (error) {
      console.error(`   ❌ Error: ${error instanceof Error ? error.message : 'Unknown error'}\n`);
      results.push({ ...doc.metadata, error: String(error) });
    }
  }

  return results;
}

/**
 * Test retrieval with various queries
 */
async function testRetrieval() {
  console.log('\n🔍 Testing context retrieval...\n');

  const testQueries = [
    {
      query: 'What is machine learning?',
      projectId: 'test-ai-project',
      description: 'AI-related query in AI project',
    },
    {
      query: 'How do I build a web application?',
      projectId: 'test-web-project',
      description: 'Web development query in web project',
    },
    {
      query: 'What are vector databases?',
      projectId: 'test-db-project',
      description: 'Database query in database project',
    },
    {
      query: 'Explain embeddings',
      projectId: undefined,
      description: 'Cross-project query (no filter)',
    },
  ];

  for (const test of testQueries) {
    console.log(`❓ Query: "${test.query}"`);
    console.log(`   Context: ${test.description}`);

    try {
      const result = await retrieveContext(test.query, {
        projectId: test.projectId,
        topK: 3,
        minScore: 0.5,
      });

      console.log(`   ✅ Found ${result.sources.length} relevant chunks:`);
      result.sources.forEach((source, idx) => {
        console.log(`      ${idx + 1}. Score: ${source.score.toFixed(3)} | Source: ${source.sourceFile || 'N/A'}`);
      });
      console.log('');
    } catch (error) {
      console.error(`   ❌ Error: ${error instanceof Error ? error.message : 'Unknown error'}\n`);
    }
  }
}

/**
 * Get and display statistics
 */
async function displayStatistics() {
  console.log('\n📊 Qdrant Collection Statistics:\n');

  try {
    const vectorStore = getVectorStore();

    if (typeof vectorStore.getStats === 'function') {
      const stats = await vectorStore.getStats();
      console.log(`Total Chunks:       ${stats.totalChunks.toLocaleString()}`);
      console.log(`Vector Dimension:   ${stats.vectorDimension}`);
      console.log(`Indexed Fields:     ${stats.indexedFields?.join(', ') || 'N/A'}`);
    } else {
      const size = typeof vectorStore.size === 'function' ? await vectorStore.size() : vectorStore.size();
      console.log(`Total Chunks:       ${size}`);
    }

    // Get project breakdown
    console.log('\n📁 Project Breakdown:');
    const projects = ['test-ai-project', 'test-web-project', 'test-db-project'];

    for (const projectId of projects) {
      const result = await retrieveContext('test', {
        projectId,
        topK: 100,
        minScore: 0.0,
      });
      console.log(`   ${projectId}: ${result.sources.length} chunks`);
    }

  } catch (error) {
    console.error(`Error getting statistics: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

/**
 * Main execution
 */
async function main() {
  console.log('═══════════════════════════════════════════════════════');
  console.log('   🧪 QDRANT INDEXING & RETRIEVAL TEST');
  console.log('═══════════════════════════════════════════════════════\n');

  try {
    // Step 1: Index documents
    console.log('STEP 1: Indexing Test Documents');
    console.log('───────────────────────────────────────────────────────\n');
    const indexResults = await indexTestDocuments();

    // Step 2: Wait a moment for indexing to complete
    console.log('⏳ Waiting for indexing to complete...\n');
    await new Promise(resolve => setTimeout(resolve, 2000));

    // Step 3: Test retrieval
    console.log('STEP 2: Testing Context Retrieval');
    console.log('───────────────────────────────────────────────────────\n');
    await testRetrieval();

    // Step 4: Display statistics
    console.log('STEP 3: Collection Statistics');
    console.log('───────────────────────────────────────────────────────');
    await displayStatistics();

    // Summary
    console.log('\n═══════════════════════════════════════════════════════');
    console.log('   ✅ TEST COMPLETED SUCCESSFULLY');
    console.log('═══════════════════════════════════════════════════════\n');

    const successCount = indexResults.filter(r => !r.error).length;
    console.log(`📊 Summary:`);
    console.log(`   Documents indexed: ${successCount}/${testDocuments.length}`);
    console.log(`   Total chunks: ${indexResults.reduce((sum, r) => sum + (r.chunksCreated || 0), 0)}`);
    console.log('\n💡 Next steps:');
    console.log('   1. View in Qdrant UI: http://localhost:3100');
    console.log('   2. Check health: curl http://localhost:9002/api/rag/health');
    console.log('   3. View stats: npm run qdrant:stats\n');

  } catch (error) {
    console.error('\n❌ Test failed:', error);
    process.exit(1);
  }
}

// Run if executed directly
if (require.main === module) {
  main().catch(console.error);
}

export { indexTestDocuments, testRetrieval, displayStatistics };
"}

