/**
 * Performance Comparison Component
 * Compares performance with/without caching and reranking
 */

import React, { useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Play, Loader2 } from 'lucide-react';
import { Progress } from '@/components/ui/progress';

interface BenchmarkResult {
  scenario: string;
  avgTime: number;
  minTime: number;
  maxTime: number;
  cacheHits: number;
  totalQueries: number;
}

export function PerformanceComparison() {
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState<BenchmarkResult[]>([]);
  const [progress, setProgress] = useState(0);

  const runBenchmark = async () => {
    setLoading(true);
    setProgress(0);
    setResults([]);

    try {
      const response = await fetch('/api/demo/benchmark', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      });

      const reader = response.body?.getReader();
      const decoder = new TextDecoder();

      if (reader) {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          const chunk = decoder.decode(value);
          const lines = chunk.split('\n').filter(l => l.trim());

          for (const line of lines) {
            if (line.startsWith('data: ')) {
              const data = JSON.parse(line.slice(6));

              if (data.progress) {
                setProgress(data.progress);
              }

              if (data.result) {
                setResults(prev => [...prev, data.result]);
              }
            }
          }
        }
      }
    } catch (error) {
      console.error('Benchmark failed:', error);
    } finally {
      setLoading(false);
    }
  };

  const getSpeedupPercent = (baseline: number, optimized: number) => {
    return ((baseline - optimized) / baseline * 100).toFixed(1);
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>Performance Comparison</CardTitle>
        <CardDescription>
          Benchmark different configurations to see the impact of caching and re-ranking
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm text-muted-foreground">
