{"file_path": "src/components/admin/rag-tester/RAGQueryTesterInterface.tsx", "initial_content": "'use client';

/**
 * RAG Query Tester Interface
 * Complete testing interface for RAG queries
 */

import React, { useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Slider } from '@/components/ui/slider';
import { Switch } from '@/components/ui/switch';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Search, Loader2, CheckCircle, Clock, Database, Zap } from 'lucide-react';
import { Alert, AlertDescription } from '@/components/ui/alert';

interface SearchResult {
  content: string;
  score: number;
  sourceFile?: string;
  projectId?: string;
  type: string;
  chunkIndex: number;
}

interface SearchResponse {
  context: string;
  sources: SearchResult[];
  query: string;
  searchTime?: number;
  cacheHit?: boolean;
}

export function RAGQueryTesterInterface() {
  const [query, setQuery] = useState('');
  const [projectId, setProjectId] = useState('');
  const [topK, setTopK] = useState(5);
  const [minScore, setMinScore] = useState(0.5);
  const [useCache, setUseCache] = useState(true);
  const [rerank, setRerank] = useState(false);
  const [rerankStrategy, setRerankStrategy] = useState<string>('hybrid');

  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState<SearchResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [searchTime, setSearchTime] = useState<number | null>(null);

  const handleSearch = async () => {
    if (!query.trim()) {
      setError('Please enter a query');
      return;
    }

    setLoading(true);
    setError(null);
    const startTime = Date.now();

    try {
      const response = await fetch('/api/admin/rag-test', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          query,
          projectId: projectId || undefined,
          topK,
          minScore,
          useCache,
          rerank,
          rerankStrategy,
        }),
      });

      if (!response.ok) {
        throw new Error(`Search failed: ${response.statusText}`);
      }

      const data = await response.json();
      setResults(data);
      setSearchTime(Date.now() - startTime);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Search failed');
      setResults(null);
    } finally {
      setLoading(false);
    }
  };

  const sampleQueries = [
    'What is quantum computing?',
    'Explain TypeScript utility types',
    'How does machine learning work?',
    'What are vector databases?',
  ];

  return (
    <div className="space-y-6">
      {/* Query Input */}
      <Card>
        <CardHeader>
          <CardTitle>Search Query</CardTitle>
          <CardDescription>
            Enter your query to test RAG search with Ollama + Qdrant
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Main Query Input */}
          <div className="space-y-2">
            <Label htmlFor="query">Query</Label>
            <div className="flex gap-2">
              <Input
                id="query"
                placeholder="Enter your search query..."
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && !loading && handleSearch()}
                disabled={loading}
                className="flex-1"
              />
              <Button onClick={handleSearch} disabled={loading || !query.trim()}>
                {loading ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Search className="h-4 w-4" />
                )}
              </Button>
            </div>
          </div>

          {/* Sample Queries */}
          <div className="space-y-2">
            <Label>Quick Tests:</Label>
            <div className="flex flex-wrap gap-2">
              {sampleQueries.map((sample, idx) => (
                <Badge
                  key={idx}
                  variant="outline"
                  className="cursor-pointer hover:bg-primary hover:text-primary-foreground"
                  onClick={() => setQuery(sample)}
                >
                  {sample}
                </Badge>
              ))}
            </div>
          </div>

          {/* Filters */}
          <div className="grid gap-4 md:grid-cols-2">
            <div className="space-y-2">
              <Label htmlFor="projectId">Project ID (Optional)</Label>
              <Input
                id="projectId"
                placeholder="Filter by project"
                value={projectId}
                onChange={(e) => setProjectId(e.target.value)}
                disabled={loading}
              />
            </div>

            <div className="space-y-2">
              <Label>Re-ranking Strategy</Label>
              <Select
                value={rerankStrategy}
                onValueChange={setRerankStrategy}
                disabled={loading || !rerank}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="hybrid">Hybrid (Semantic + Keyword)</SelectItem>
                  <SelectItem value="cross-encoder">Cross-Encoder (Most Accurate)</SelectItem>
                  <SelectItem value="bm25">BM25 (Keyword Only)</SelectItem>
                  <SelectItem value="reciprocal-rank-fusion">RRF (Ensemble)</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* Sliders */}
          <div className="grid gap-4 md:grid-cols-2">
            <div className="space-y-2">
              <Label>Top K Results: {topK}</Label>
              <Slider
                value={[topK]}
                onValueChange={([value]) => setTopK(value)}
                min={1}
                max={20}
                step={1}
                disabled={loading}
              />
            </div>

            <div className="space-y-2">
              <Label>Min Score: {minScore.toFixed(2)}</Label>
              <Slider
                value={[minScore]}
                onValueChange={([value]) => setMinScore(value)}
                min={0}
                max={1}
                step={0.05}
                disabled={loading}
              />
            </div>
          </div>

          {/* Switches */}
          <div className="flex items-center gap-6">
            <div className="flex items-center space-x-2">
              <Switch
                id="cache"
                checked={useCache}
                onCheckedChange={setUseCache}
                disabled={loading}
              />
              <Label htmlFor="cache">Use Cache</Label>
            </div>

            <div className="flex items-center space-x-2">
              <Switch
                id="rerank"
                checked={rerank}
                onCheckedChange={setRerank}
                disabled={loading}
              />
              <Label htmlFor="rerank">Re-ranking</Label>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Performance Metrics */}
      {searchTime !== null && results && (
        <div className="grid gap-4 md:grid-cols-4">
          <Card>
            <CardContent className="pt-6">
              <div className="flex items-center gap-2">
                <Clock className="h-4 w-4 text-muted-foreground" />
                <div>
                  <div className="text-2xl font-bold">{searchTime}ms</div>
                  <div className="text-xs text-muted-foreground">Search Time</div>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="pt-6">
              <div className="flex items-center gap-2">
                <Database className="h-4 w-4 text-muted-foreground" />
                <div>
                  <div className="text-2xl font-bold">{results.sources.length}</div>
                  <div className="text-xs text-muted-foreground">Results Found</div>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="pt-6">
              <div className="flex items-center gap-2">
                {results.cacheHit ? (
                  <CheckCircle className="h-4 w-4 text-green-500" />
                ) : (
                  <Zap className="h-4 w-4 text-muted-foreground" />
                )}
                <div>
                  <div className="text-2xl font-bold">{results.cacheHit ? 'Yes' : 'No'}</div>
                  <div className="text-xs text-muted-foreground">Cache Hit</div>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="pt-6">
              <div className="flex items-center gap-2">
                <div>
                  <div className="text-2xl font-bold">
                    {results.sources.length > 0 ? results.sources[0].score.toFixed(3) : 'N/A'}
                  </div>
                  <div className="text-xs text-muted-foreground">Top Score</div>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Error Display */}
      {error && (
        <Alert variant="destructive">
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}

      {/* Search Results */}
      {results && results.sources.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>Search Results ({results.sources.length})</CardTitle>
            <CardDescription>
              Showing top {results.sources.length} results ranked by relevance
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            {results.sources.map((result, idx) => (
              <Card key={idx} className="border-l-4 border-l-primary">
                <CardContent className="pt-4">
                  <div className="space-y-3">
                    {/* Header with badges */}
                    <div className="flex items-start justify-between gap-4">
                      <div className="flex flex-wrap items-center gap-2">
                        <Badge variant="default" className="font-mono">
                          #{idx + 1}
                        </Badge>
                        <Badge variant="secondary">
                          Score: {result.score.toFixed(3)}
                        </Badge>
                        {result.sourceFile && (
                          <Badge variant="outline">
                            📄 {result.sourceFile}
                          </Badge>
                        )}
                        {result.projectId && (
                          <Badge variant="outline">
                            🏷️ {result.projectId}
                          </Badge>
                        )}
                        <Badge variant="outline">
                          {result.type}
                        </Badge>
                        <Badge variant="outline" className="font-mono text-xs">
                          Chunk {result.chunkIndex}
                        </Badge>
                      </div>
                    </div>

                    {/* Content */}
                    <div className="rounded-md bg-muted/50 p-4">
                      <p className="text-sm whitespace-pre-wrap leading-relaxed">
                        {result.content}
                      </p>
                    </div>

                    {/* Relevance indicator */}
                    <div className="flex items-center gap-2">
                      <div className="flex-1 h-2 bg-muted rounded-full overflow-hidden">
                        <div
                          className="h-full bg-primary transition-all"
                          style={{ width: `${result.score * 100}%` }}
                        />
                      </div>
                      <span className="text-xs text-muted-foreground">
                        {(result.score * 100).toFixed(1)}% match
                      </span>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </CardContent>
        </Card>
      )}

      {/* No Results */}
      {results && results.sources.length === 0 && (
        <Card>
          <CardContent className="py-12">
            <div className="text-center text-muted-foreground">
              <p className="text-lg font-medium mb-2">No results found</p>
              <p className="text-sm">
                Try adjusting your query, lowering the min score threshold, or checking if documents are indexed.
              </p>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Empty State */}
      {!loading && !results && !error && (
        <Card>
          <CardContent className="py-12">
            <div className="text-center text-muted-foreground">
              <Search className="h-12 w-12 mx-auto mb-4 opacity-50" />
              <p className="text-lg font-medium mb-2">Ready to search</p>
              <p className="text-sm">
                Enter a query above to test the RAG system with real-time results
              </p>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}
"}

{"file_path": "src/app/api/admin/rag-test/route.ts", "initial_content": "/**
 * Admin RAG Test API
 * 
 * Test RAG queries with full control and detailed results
 */

import { NextRequest, NextResponse } from 'next/server';
import { retrieveContext } from '@/lib/rag/retrieval';
import { getCacheManager } from '@/lib/rag/cache';

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const {
      query,
      projectId,
      topK = 5,
      minScore = 0.5,
      useCache = true,
      rerank = false,
      rerankStrategy = 'hybrid',
    } = body;

    if (!query || typeof query !== 'string') {
      return NextResponse.json(
        { error: 'Query is required' },
        { status: 400 }
      );
    }

    // Check if will be cache hit (for reporting)
    let cacheHit = false;
    if (useCache) {
      const cacheManager = getCacheManager();
      const cache = cacheManager.getSearchCache();
      cacheHit = cache.getResults(query, { projectId, topK, minScore }) !== null;
    }

    // Perform search
    const result = await retrieveContext(query, {
      projectId,
      topK,
      minScore,
      useCache,
      rerank,
      rerankStrategy,
    });

    return NextResponse.json({
      ...result,
      cacheHit,
      timestamp: new Date().toISOString(),
    });

  } catch (error) {
    console.error('RAG test error:', error);

    return NextResponse.json(
      {
        error: error instanceof Error ? error.message : 'Search failed',
        sources: [],
        context: '',
      },
      { status: 500 }
    );
  }
}
"}

{"file_path": "src/services/document-tracking-service.ts", "initial_content": "/**
 * Document Tracking Service
 * 
 * Tracks all indexed documents in Firestore for admin management
 * - Record document uploads
 * - Store metadata (file name, chunks, timestamp, project)
 * - Enable listing and searching
 * - Support deletion tracking
 */

import { adminDb } from '@/lib/firebase/server-init';
import { Timestamp } from 'firebase-admin/firestore';

export interface IndexedDocumentRecord {
  id: string;
  projectId: string;
  userId?: string;
  sourceFile: string;
  chunksCount: number;
  fileSize: number;
  type: 'report' | 'reference' | 'context' | 'user_upload';
  timestamp: number;
  indexedAt: Timestamp;
  chunkSize: number;
  overlap: number;
  status: 'indexed' | 'failed' | 'deleted';
  errorMessage?: string;
}

const COLLECTION_NAME = 'indexed_documents';

/**
 * Record a newly indexed document
 */
export async function recordIndexedDocument(data: {
  projectId: string;
  userId?: string;
  sourceFile: string;
  chunksCount: number;
  fileSize: number;
  type: 'report' | 'reference' | 'context' | 'user_upload';
  chunkSize: number;
  overlap: number;
}): Promise<string> {
  try {
    const docRef = adminDb.collection(COLLECTION_NAME).doc();

    const record: Omit<IndexedDocumentRecord, 'id'> = {
      ...data,
      timestamp: Date.now(),
      indexedAt: Timestamp.now(),
      status: 'indexed',
    };

    await docRef.set(record);

    console.log(`📝 Recorded document: ${data.sourceFile} (${data.chunksCount} chunks)`);

    return docRef.id;
  } catch (error) {
    console.error('Error recording indexed document:', error);
    throw error;
  }
}

/**
 * Record a failed indexing attempt
 */
export async function recordFailedIndexing(data: {
  projectId: string;
  userId?: string;
  sourceFile: string;
  fileSize: number;
  type: string;
  errorMessage: string;
}): Promise<string> {
  try {
    const docRef = adminDb.collection(COLLECTION_NAME).doc();

    const record = {
      ...data,
      chunksCount: 0,
      chunkSize: 0,
      overlap: 0,
      timestamp: Date.now(),
      indexedAt: Timestamp.now(),
      status: 'failed' as const,
      errorMessage: data.errorMessage,
    };

    await docRef.set(record);

    return docRef.id;
  } catch (error) {
    console.error('Error recording failed indexing:', error);
    throw error;
  }
}

/**
 * Get all indexed documents
 */
export async function getAllIndexedDocuments(): Promise<IndexedDocumentRecord[]> {
  try {
    const snapshot = await adminDb
      .collection(COLLECTION_NAME)
      .where('status', '==', 'indexed')
      .orderBy('timestamp', 'desc')
      .limit(100)
      .get();

    const documents: IndexedDocumentRecord[] = [];

    snapshot.forEach(doc => {
      documents.push({
        id: doc.id,
        ...(doc.data() as Omit<IndexedDocumentRecord, 'id'>),
      });
    });

    return documents;
  } catch (error) {
    console.error('Error fetching indexed documents:', error);
    return [];
  }
}

/**
 * Get documents by project ID
 */
export async function getDocumentsByProject(projectId: string): Promise<IndexedDocumentRecord[]> {
  try {
    const snapshot = await adminDb
      .collection(COLLECTION_NAME)
      .where('projectId', '==', projectId)
      .where('status', '==', 'indexed')
      .orderBy('timestamp', 'desc')
      .get();

    const documents: IndexedDocumentRecord[] = [];

    snapshot.forEach(doc => {
      documents.push({
        id: doc.id,
        ...(doc.data() as Omit<IndexedDocumentRecord, 'id'>),
      });
    });

    return documents;
  } catch (error) {
    console.error('Error fetching documents by project:', error);
    return [];
  }
}

/**
 * Mark document as deleted
 */
export async function markDocumentDeleted(projectId: string): Promise<void> {
  try {
    const snapshot = await adminDb
      .collection(COLLECTION_NAME)
      .where('projectId', '==', projectId)
      .where('status', '==', 'indexed')
      .get();

    const batch = adminDb.batch();

    snapshot.forEach(doc => {
      batch.update(doc.ref, {
        status: 'deleted',
        deletedAt: Timestamp.now(),
      });
    });

    await batch.commit();

    console.log(`🗑️ Marked documents in project "${projectId}" as deleted`);
  } catch (error) {
    console.error('Error marking document as deleted:', error);
    throw error;
  }
}

/**
 * Get statistics about indexed documents
 */
export async function getDocumentStatistics(): Promise<{
  totalDocuments: number;
  totalChunks: number;
  projectCount: number;
  recentUploads: number;
}> {
  try {
    const snapshot = await adminDb
      .collection(COLLECTION_NAME)
      .where('status', '==', 'indexed')
      .get();

    let totalChunks = 0;
    const projects = new Set<string>();
    const now = Date.now();
    const oneDayAgo = now - (24 * 60 * 60 * 1000);
    let recentUploads = 0;

    snapshot.forEach(doc => {
      const data = doc.data();
      totalChunks += data.chunksCount || 0;
      projects.add(data.projectId);
      if (data.timestamp > oneDayAgo) {
        recentUploads++;
      }
    });

    return {
      totalDocuments: snapshot.size,
      totalChunks,
      projectCount: projects.size,
      recentUploads,
    };
  } catch (error) {
    console.error('Error getting document statistics:', error);
    return {
      totalDocuments: 0,
      totalChunks: 0,
      projectCount: 0,
      recentUploads: 0,
    };
  }
}

/**
 * Search documents
 */
export async function searchDocuments(query: string): Promise<IndexedDocumentRecord[]> {
  try {
    const snapshot = await adminDb
      .collection(COLLECTION_NAME)
      .where('status', '==', 'indexed')
      .orderBy('timestamp', 'desc')
      .limit(50)
      .get();

    const documents: IndexedDocumentRecord[] = [];
    const lowerQuery = query.toLowerCase();

    snapshot.forEach(doc => {
      const data = doc.data();
      const sourceFile = (data.sourceFile || '').toLowerCase();
      const projectId = (data.projectId || '').toLowerCase();

      if (sourceFile.includes(lowerQuery) || projectId.includes(lowerQuery)) {
        documents.push({
          id: doc.id,
          ...(data as Omit<IndexedDocumentRecord, 'id'>),
        });
      }
    });

    return documents;
  } catch (error) {
    console.error('Error searching documents:', error);
    return [];
  }
}
"}

